	"net/http/httptest"
	"testing"

	"github.com/gin-gonic/gin"
)

type verifyErr string

func (e verifyErr) Error() string { return string(e) }

// 1. private error unwraps to the original error
func TestVerifyPrivateUnwrap(t *testing.T) {
	orig := verifyErr("boom")
	e := &gin.Error{Err: orig, Type: gin.ErrorTypePrivate}

	if got := errors.Unwrap(e); got != error(orig) {
		t.Fatalf("errors.Unwrap(private) = %v (%T), want %v", got, got, orig)
	}
	if !errors.Is(e, orig) {
		t.Fatalf("errors.Is(private, orig) = false, want true")
	}
	var target verifyErr
	if !errors.As(e, &target) {
		t.Fatalf("errors.As(private, *verifyErr) = false, want true")
	}
	if target != orig {
		t.Fatalf("errors.As target = %q, want %q", target, orig)
	}
}

// 2. public error unwraps to nil
func TestVerifyPublicUnwrap(t *testing.T) {
	orig := verifyErr("boom")
	e := &gin.Error{Err: orig, Type: gin.ErrorTypePublic}

	if got := errors.Unwrap(e); got != nil {
		t.Fatalf("errors.Unwrap(public) = %v (%T), want nil", got, got)
	}
	if errors.Is(e, orig) {
		t.Fatalf("errors.Is(public, orig) = true, want false")
	}
	// identity still holds (errors.Is compares the error itself first)
	if !errors.Is(e, e) {
		t.Fatalf("errors.Is(public, public) = false, want true")
	}
	// SetType mutates in place and must switch unwrap behaviour
	sw := &gin.Error{Err: orig, Type: gin.ErrorTypePrivate}
	if errors.Unwrap(sw) != error(orig) {
		t.Fatalf("private before SetType: unwrap != orig")
	}
	sw.SetType(gin.ErrorTypePublic)
	if got := errors.Unwrap(sw); got != nil {
		t.Fatalf("after SetType(Public): errors.Unwrap = %v, want nil", got)
	}
}

// 3. errors.Is / errors.As through extra layers of wrapping (existing gin test relies on ErrorTypeAny)
func TestVerifyNestedWrapping(t *testing.T) {
	orig := verifyErr("boom")

	// ErrorTypeAny includes the private bit -> still unwrappable (back-compat with TestErrorUnwrap)
	anyErr := fmt.Errorf("wrapped: %w", &gin.Error{Err: orig, Type: gin.ErrorTypeAny})
	if !errors.Is(anyErr, orig) {
		t.Fatalf("errors.Is(ErrorTypeAny wrapped) = false, want true")
	}
	var te verifyErr
	if !errors.As(anyErr, &te) {
		t.Fatalf("errors.As(ErrorTypeAny wrapped) = false, want true")
	}

	// private, two layers
	priv := fmt.Errorf("outer: %w", &gin.Error{Err: orig, Type: gin.ErrorTypePrivate})
	if !errors.Is(priv, orig) {
		t.Fatalf("errors.Is(private wrapped) = false, want true")
	}
	var ge *gin.Error
	if !errors.As(priv, &ge) {
		t.Fatalf("errors.As(private wrapped, *gin.Error) = false, want true")
	}
}

// 4. Error() string (and JSON) unchanged by the fix
func TestVerifyErrorStringUnchanged(t *testing.T) {
	orig := errors.New("test error")
	for _, typ := range []gin.ErrorType{gin.ErrorTypePrivate, gin.ErrorTypePublic, gin.ErrorTypeAny, gin.ErrorTypeBind} {
		e := &gin.Error{Err: orig, Type: typ}
		if got := e.Error(); got != "test error" {
			t.Fatalf("Error() (type %d) = %q, want %q", typ, got, "test error")
		}
		if got := e.JSON(); fmt.Sprint(got) != "map[error:test error]" {
			t.Fatalf("JSON() (type %d) = %v, want map[error:test error]", typ, got)
		}
	}
}

// 5. end-to-end: errors recorded by gin's own API
func TestVerifyContextErrors(t *testing.T) {
	orig := verifyErr("ctx boom")
	r := gin.New()
	var fromError, fromAbort *gin.Error
	r.GET("/e", func(c *gin.Context) { fromError = c.Error(orig) })
	r.GET("/abort", func(c *gin.Context) { fromAbort = c.AbortWithError(http.StatusBadRequest, orig) })

	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/e", nil))
	if fromError == nil || fromError.Type != gin.ErrorTypePrivate {
		t.Fatalf("c.Error type = %v, want private", fromError)
	}
	if !errors.Is(fromError, orig) || errors.Unwrap(fromError) != error(orig) {
		t.Fatalf("c.Error result not unwrappable: Is=%v Unwrap=%v", errors.Is(fromError, orig), errors.Unwrap(fromError))
	}

	w = httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/abort", nil))
	if fromAbort == nil || !errors.Is(fromAbort, orig) {
		t.Fatalf("c.AbortWithError result not unwrappable: %v", fromAbort)
	}

	// a user-marked public error must NOT unwrap
	pub := (&gin.Error{Err: orig, Type: gin.ErrorTypePrivate}).SetType(gin.ErrorTypePublic)
	if errors.Unwrap(pub) != nil {
		t.Fatalf("public error unwraps to %v, want nil", errors.Unwrap(pub))
	}
}
