	"strings"

	"github.com/gin-gonic/gin"
)

type myErr string

func (e myErr) Error() string { return string(e) }




func bindDemo() {
	r := gin.New()
	var last *gin.Error
	var bindErr error
	r.POST("/bind", func(c *gin.Context) {
		var p payload
		bindErr = c.ShouldBindJSON(&p)
		last = c.Errors.Last()
	})
	r.POST("/mustbind", func(c *gin.Context) {
		var p payload
		bindErr = c.ShouldBindJSON(&p)
		c.AbortWithError(http.StatusBadRequest, bindErr).SetType(gin.ErrorTypeBind) // nolint: errcheck
		last = c.Errors.Last()
	})
	w := httptest.NewRecorder()
	req := httptest.NewRequest("POST", "/bind", strings.NewReader(`{}`))
	req.Header.Set("Content-Type", "application/json")
	r.ServeHTTP(w, req)
	if last == nil { fmt.Println("[ShouldBindJSON] no error registered in c.Errors") } else { fmt.Printf("[ShouldBindJSON] last.Type=%d unwrap=%v Is=%v\n", uint64(last.Type), errors.Unwrap(last), errors.Is(last, bindErr)) }

	w = httptest.NewRecorder()
	req = httptest.NewRequest("POST", "/mustbind", strings.NewReader(`{}`))
	req.Header.Set("Content-Type", "application/json")
	r.ServeHTTP(w, req)
	fmt.Printf("[ErrorTypeBind] last.Type=%d unwrap=%v errors.Is(last,bindErr)=%v\n", uint64(last.Type), errors.Unwrap(last), errors.Is(last, bindErr))

	inner := errors.New("inner")
	pub := &gin.Error{Err: inner, Type: gin.ErrorTypePublic}
	wrapped := fmt.Errorf("wrap: %w", pub)
	var parsed *gin.Error
	fmt.Printf("[errors.As] wrapped-public: As(*gin.Error)=%v Is(inner)=%v\n", errors.As(wrapped, &parsed), errors.Is(wrapped, inner))
	c := &gin.Context{}
	got := c.Error(wrapped)
	fmt.Printf("[c.Error(wrapped public)] stored.Type=%d (want 2=ErrorTypePublic), stored==pub? %v\n", uint64(got.Type), got == pub)
}

type payload struct {
	Name string `json:"name" binding:"required"`
}

func main() {
	inner := myErr("boom")
	for _, typ := range []gin.ErrorType{gin.ErrorTypePrivate, gin.ErrorTypePublic, gin.ErrorTypeBind, gin.ErrorTypeRender, gin.ErrorTypeAny} {
		e := &gin.Error{Err: inner, Type: typ}
		var t myErr
		fmt.Printf("type=%-20d Unwrap=%v Is=%v As=%v\n", uint64(typ), errors.Unwrap(e), errors.Is(e, inner), errors.As(e, &t))
	}
	wrapped := fmt.Errorf("outer: %w", &gin.Error{Err: inner, Type: gin.ErrorTypePrivate})
	fmt.Println("nested fmt.Errorf Is:", errors.Is(wrapped, inner))

	// end-to-end through Context.Error / AbortWithError
	r := gin.New()
	r.GET("/e", func(c *gin.Context) { c.Error(inner) })
	r.GET("/abort", func(c *gin.Context) { c.AbortWithError(http.StatusBadRequest, inner) })
	r.GET("/bind", func(c *gin.Context) { c.AbortWithError(http.StatusBadRequest, inner).SetType(gin.ErrorTypeBind) })
	for _, p := range []string{"/e", "/abort", "/bind"} {
		w := httptest.NewRecorder()
		r.ServeHTTP(w, httptest.NewRequest("GET", p, nil))
	}
	// inspect via a middleware-less route capturing c.Errors
	r2 := gin.New()
	var captured []*gin.Error
	r2.GET("/e", func(c *gin.Context) { c.Error(inner); captured = append(captured, c.Errors.Last()) })
	r2.GET("/bind", func(c *gin.Context) { captured = append(captured, c.AbortWithError(http.StatusBadRequest, inner).SetType(gin.ErrorTypeBind)) })
	for _, p := range []string{"/e", "/bind"} {
		w := httptest.NewRecorder()
		r2.ServeHTTP(w, httptest.NewRequest("GET", p, nil))
	}
	for i, e := range captured {
		fmt.Printf("captured[%d] type=%d Unwrap=%v Is=%v\n", i, uint64(e.Type), errors.Unwrap(e), errors.Is(e, inner))
	}

	bindDemo()
	extra()
	// nil Err
	func() {
		defer func() { fmt.Println("recovered:", recover()) }()
		fmt.Println("nil *Error Unwrap:", errors.Unwrap((*gin.Error)(nil)))
	}()
}
