package main

import (
	"errors"
	"fmt"

	"github.com/gin-gonic/gin"
)

func extra() {
	// ByType(ErrorTypeAny) aliasing check
	c := &gin.Context{}
	c.Error(errors.New("a"))
	c.Error(errors.New("b"))
	got := c.Errors.ByType(gin.ErrorTypeAny)
	got[0] = &gin.Error{Err: errors.New("mutated"), Type: gin.ErrorTypePublic}
	fmt.Println("[ByType(Any) aliasing] c.Errors[0] now:", c.Errors[0].Error())

	// Type == 0
	e0 := &gin.Error{Err: errors.New("zero-type")}
	fmt.Println("[Type=0] Unwrap:", errors.Unwrap(e0), "Is:", errors.Is(e0, e0.Err))

	// nil Err panic
	func() {
		defer func() { fmt.Println("[&Error{} .Error()] recovered:", recover()) }()
		fmt.Println((&gin.Error{}).Error())
	}()
	func() {
		defer func() { fmt.Println("[&Error{} .JSON()] recovered:", recover()) }()
		fmt.Println((&gin.Error{}).JSON())
	}()
}
